import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Horde: Archived Wiki Version","description":"","frontmatter":{},"headers":[],"relativePath":"formats/horde/variants/wiki.md","filePath":"formats/horde/variants/wiki.md","lastUpdated":null}'),o={name:"formats/horde/variants/wiki.md"};function s(n,e,l,d,h,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="horde-archived-wiki-version" tabindex="-1">Horde: Archived Wiki Version <a class="header-anchor" href="#horde-archived-wiki-version" aria-label="Permalink to &quot;Horde: Archived Wiki Version&quot;">​</a></h1><p><a href="./../">Horde versions</a> · <strong>Rules: wiki snapshot preserved in this repository</strong></p><p>This page gives the procedures recorded in the repository&#39;s wiki notes. It is a distinct source version, not a claim that every Horde group uses these rules or that the snapshot matches the current wiki.</p><h2 id="players-and-materials" tabindex="-1">Players and materials <a class="header-anchor" href="#players-and-materials" aria-label="Permalink to &quot;Players and materials&quot;">​</a></h2><p>Use one to four survivors and an automated Horde. Survivors bring their own decks, normally Commander decks. A typical Horde has 100 cards: approximately 60 creature-token cards and 40 ordinary cards, selected to avoid decisions and suit the Horde&#39;s theme.</p><p>Prepare the tokens, counters, and shared life tracker needed by those decks.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>Shuffle survivor decks and the Horde. Prepare commanders where applicable.</li><li>Survivors draw opening hands and take normal mulligans.</li><li>Start the survivor team at <strong>20 life per player</strong>, combined into one shared total.</li><li>Survivors take <strong>three shared setup turns</strong> before the Horde&#39;s first turn.</li><li>After setup, alternate survivor and Horde turns.</li></ol><p>The snapshot describes random removal of Horde cards as a difficulty option, but does not supply the original article&#39;s exact player-count table. If using that option, record how many cards are set aside.</p><h2 id="survivor-turns" tabindex="-1">Survivor turns <a class="header-anchor" href="#survivor-turns" aria-label="Permalink to &quot;Survivor turns&quot;">​</a></h2><p>Survivors take their phases and steps simultaneously, similar to shared-team-turn Magic. They coordinate attacks and blocks as a team. Each player uses their own cards and resources; damage and life changes affect the shared total.</p><h2 id="horde-turns" tabindex="-1">Horde turns <a class="header-anchor" href="#horde-turns" aria-label="Permalink to &quot;Horde turns&quot;">​</a></h2><ol><li>At the start of the Horde&#39;s turn, reveal cards until reaching a non-token card or exhausting the library.</li><li>Cast the revealed token cards first, then the non-token card if there is one.</li><li>The Horde also casts cards from its hand or graveyard when applicable under their instructions.</li><li>Proceed to combat. Horde creatures have haste and must attack if able.</li></ol><p>The Horde has unlimited mana. Make any required choices as randomly as possible among legal options. Its spells and abilities still interact with the normal Magic stack.</p><p>The archived snapshot does not separately state a universal blocking restriction; do not silently import HordeMagic.com&#39;s defender-only restriction into it.</p><h2 id="damage-life-loss-and-life-gain" tabindex="-1">Damage, life loss, and life gain <a class="header-anchor" href="#damage-life-loss-and-life-gain" aria-label="Permalink to &quot;Damage, life loss, and life gain&quot;">​</a></h2><p>The Horde has no life total. Damage <strong>or life loss</strong> that would affect it mills that many cards from its library.</p><p>Lifelink works for survivor creatures: damage can both mill the Horde and gain survivor life. Horde life gain does not return milled cards to its library in this recorded version.</p><h2 id="winning-and-losing" tabindex="-1">Winning and losing <a class="header-anchor" href="#winning-and-losing" aria-label="Permalink to &quot;Winning and losing&quot;">​</a></h2><p>Survivors win when all three conditions hold:</p><ul><li>The Horde library is empty.</li><li>The Horde hand is empty.</li><li>The Horde controls no creatures.</li></ul><p>This differs from the HordeMagic.com requirement to clear its entire battlefield. A noncreature Horde permanent does not, by itself, prevent this snapshot&#39;s victory condition.</p><p>The Horde wins when shared survivor life reaches zero or less.</p><h2 id="recorded-survivor-ban-list" tabindex="-1">Recorded survivor ban list <a class="header-anchor" href="#recorded-survivor-ban-list" aria-label="Permalink to &quot;Recorded survivor ban list&quot;">​</a></h2><p>Aether Flash; Aurification; Barbed Foliage; Caltrops; Crawlspace; Dueling Grounds; Dread; Elesh Norn, Grand Cenobite; Ensnaring Bridge; Eradicate; Grindstone; Haunting Echoes; Island Sanctuary; Lethal Vapors; Leyline of Singularity; Magus of the Moat; Mind Funeral; Moat; No Mercy; Platinum Angel; Platinum Emperion; Silent Arbiter; Solitary Confinement; Stormtide Leviathan; Surgical Extraction; Tainted Aether; Teferi&#39;s Moat; Time Stretch; Trepanation Blade; Urabrask the Hidden.</p><p>Apply the underlying survivor deck format&#39;s restrictions too.</p><h2 id="optional-difficulty-changes" tabindex="-1">Optional difficulty changes <a class="header-anchor" href="#optional-difficulty-changes" aria-label="Permalink to &quot;Optional difficulty changes&quot;">​</a></h2><p>The snapshot proposes the following adjustable rules. Choose and state their values before play:</p><ul><li>Change the number of survivor setup turns.</li><li>Change each survivor&#39;s starting-life contribution.</li><li>Randomly remove a specified portion of the Horde before play.</li><li>Change the Horde&#39;s card list or use a defined sideboard.</li><li>Replace random Horde decisions with a survivor-consensus decision procedure.</li><li>Let Horde token cards remain in the graveyard instead of ceasing to exist.</li><li>Permit or prohibit attacks during survivor setup turns.</li></ul><p>Changing token-to-spell ratios is also a deck-design adjustment. A boxed set must state the actual chosen settings rather than merely saying its difficulty is adjusted.</p><p>Source: <a href="./../sources/horde-magic-wiki.html">the repository&#39;s archived wiki notes</a>, attributed there to <a href="https://mtg.fandom.com/wiki/Horde_Magic#Rules_for_The_Horde" target="_blank" rel="noreferrer">MTG Wiki&#39;s Horde Magic rules</a>.</p>',31)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
